//! The OCSF templates' former `dataset: signals` SQL pivots, frozen as fixed
//! strings when the templates moved to nPL (NAN-5621), so the SQL-to-nPL
//! converter keeps its coverage of those shapes.

/// `(template slug, pivot name, SQL)`.
pub(super) const FORMER_TEMPLATE_SIGNALS_SQL: &[(&str, &str, &str)] = &[
    ("detection-signals", "signal_clusters", r#"SELECT risk_entity, uniqExact(rule_id) AS distinct_rules, count() AS fires, countIf(severity IN ('low', 'info', 'informational')) AS low_fires, groupUniqArray(10)(rule_name) AS rules, min(timestamp) AS first_fire, max(timestamp) AS last_fire FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND risk_entity != '' GROUP BY risk_entity ORDER BY distinct_rules DESC, fires DESC, risk_entity ASC"#),
    ("detection-signals", "top_entity_events", r#"SELECT id, timestamp, source_type, class_uid, `device.hostname`, `actor.user.name`, `src_endpoint.ip`, `dst_endpoint.ip`, `actor.process.cmd_line` FROM {events} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND id IN (SELECT matched_log_id FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND risk_entity IN (SELECT risk_entity FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND risk_entity != '' GROUP BY risk_entity ORDER BY uniqExact(rule_id) DESC, risk_entity ASC LIMIT 10)) ORDER BY timestamp DESC"#),
    ("dns-tunneling", "dns_parent_domain_shape", r#"SELECT parent_domain AS parent_domain, uniq(name) AS distinct_names, count() AS queries, countIf(qtype IN ('TXT', 'NULL')) AS txt_null_queries, round(txt_null_queries / queries, 3) AS txt_null_share, round(avg(length(name)), 1) AS avg_name_length, quantileExact(0.5)(length(lbl)) AS median_label_length, max(length(lbl)) AS max_label_length, round(avg(entropy), 3) AS label_entropy_bits, uniq(host_ip) AS source_ips, groupUniqArray(5)(host_name) AS source_hosts, groupUniqArray(5)(host_ip) AS source_ip_sample, countIf(detected) AS already_detected, min(ts) AS first_seen, max(ts) AS last_seen FROM (SELECT timestamp AS ts, id, `query.hostname` AS name, upper(toString(event.query.type)) AS qtype, `src_endpoint.ip` AS host_ip, `src_endpoint.hostname` AS host_name, cutToFirstSignificantSubdomain(`query.hostname`) AS parent_domain, splitByChar('.', `query.hostname`)[1] AS lbl, splitByString('', lbl) AS chars, arraySum(arrayMap(c -> -(c / length(lbl)) * log2(c / length(lbl)), arrayMap(ch -> countEqual(chars, ch), arrayDistinct(chars)))) AS entropy, id IN (SELECT matched_log_id FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')}) AS detected FROM {events} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND class_uid = 4003 AND `query.hostname` != '') WHERE parent_domain != '' AND parent_domain != name GROUP BY parent_domain HAVING distinct_names >= 20 AND ((median_label_length >= 25) + (label_entropy_bits >= 4.0) + (txt_null_share >= 0.5)) >= 2 ORDER BY distinct_names DESC, parent_domain ASC"#),
    ("dns-tunneling", "dns_tunnel_candidate_queries", r#"SELECT id, ts AS timestamp, host_name AS `src_endpoint.hostname`, host_ip AS `src_endpoint.ip`, name AS `query.hostname`, qtype AS `query.type`, parent_domain, length(lbl) AS label_length, detected AS already_detected FROM (SELECT timestamp AS ts, id, `query.hostname` AS name, upper(toString(event.query.type)) AS qtype, `src_endpoint.ip` AS host_ip, `src_endpoint.hostname` AS host_name, cutToFirstSignificantSubdomain(`query.hostname`) AS parent_domain, splitByChar('.', `query.hostname`)[1] AS lbl, splitByString('', lbl) AS chars, arraySum(arrayMap(c -> -(c / length(lbl)) * log2(c / length(lbl)), arrayMap(ch -> countEqual(chars, ch), arrayDistinct(chars)))) AS entropy, id IN (SELECT matched_log_id FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')}) AS detected FROM {events} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND class_uid = 4003 AND `query.hostname` != '') WHERE parent_domain IN (SELECT parent_domain FROM (SELECT parent_domain AS parent_domain, uniq(name) AS distinct_names, count() AS queries, countIf(qtype IN ('TXT', 'NULL')) AS txt_null_queries, round(txt_null_queries / queries, 3) AS txt_null_share, round(avg(length(name)), 1) AS avg_name_length, quantileExact(0.5)(length(lbl)) AS median_label_length, max(length(lbl)) AS max_label_length, round(avg(entropy), 3) AS label_entropy_bits, uniq(host_ip) AS source_ips, groupUniqArray(5)(host_name) AS source_hosts, groupUniqArray(5)(host_ip) AS source_ip_sample, countIf(detected) AS already_detected, min(ts) AS first_seen, max(ts) AS last_seen FROM (SELECT timestamp AS ts, id, `query.hostname` AS name, upper(toString(event.query.type)) AS qtype, `src_endpoint.ip` AS host_ip, `src_endpoint.hostname` AS host_name, cutToFirstSignificantSubdomain(`query.hostname`) AS parent_domain, splitByChar('.', `query.hostname`)[1] AS lbl, splitByString('', lbl) AS chars, arraySum(arrayMap(c -> -(c / length(lbl)) * log2(c / length(lbl)), arrayMap(ch -> countEqual(chars, ch), arrayDistinct(chars)))) AS entropy, id IN (SELECT matched_log_id FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')}) AS detected FROM {events} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND class_uid = 4003 AND `query.hostname` != '') WHERE parent_domain != '' AND parent_domain != name GROUP BY parent_domain HAVING distinct_names >= 20 AND ((median_label_length >= 25) + (label_entropy_bits >= 4.0) + (txt_null_share >= 0.5)) >= 2)) ORDER BY parent_domain ASC, `src_endpoint.hostname` ASC, timestamp DESC LIMIT 25 BY parent_domain, `src_endpoint.hostname`, `src_endpoint.ip`"#),
    ("intrusion-chain", "dns_parent_domain_shape", r#"SELECT parent_domain AS parent_domain, uniq(name) AS distinct_names, count() AS queries, countIf(qtype IN ('TXT', 'NULL')) AS txt_null_queries, round(txt_null_queries / queries, 3) AS txt_null_share, round(avg(length(name)), 1) AS avg_name_length, quantileExact(0.5)(length(lbl)) AS median_label_length, max(length(lbl)) AS max_label_length, round(avg(entropy), 3) AS label_entropy_bits, uniq(host_ip) AS source_ips, groupUniqArray(5)(host_name) AS source_hosts, groupUniqArray(5)(host_ip) AS source_ip_sample, countIf(detected) AS already_detected, min(ts) AS first_seen, max(ts) AS last_seen FROM (SELECT timestamp AS ts, id, `query.hostname` AS name, upper(toString(event.query.type)) AS qtype, `src_endpoint.ip` AS host_ip, `src_endpoint.hostname` AS host_name, cutToFirstSignificantSubdomain(`query.hostname`) AS parent_domain, splitByChar('.', `query.hostname`)[1] AS lbl, splitByString('', lbl) AS chars, arraySum(arrayMap(c -> -(c / length(lbl)) * log2(c / length(lbl)), arrayMap(ch -> countEqual(chars, ch), arrayDistinct(chars)))) AS entropy, id IN (SELECT matched_log_id FROM {signals} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')}) AS detected FROM {events} WHERE timestamp >= {earliest:DateTime64(6, 'UTC')} AND timestamp <= {latest:DateTime64(6, 'UTC')} AND class_uid = 4003 AND `query.hostname` != '') WHERE parent_domain != '' AND parent_domain != name GROUP BY parent_domain HAVING distinct_names >= 20 AND ((median_label_length >= 25) + (label_entropy_bits >= 4.0) + (txt_null_share >= 0.5)) >= 2 ORDER BY distinct_names DESC, parent_domain ASC"#),
];
